mapper.sql:
(
    n.is_broadcast = 1
    OR EXISTS (
        SELECT 1 FROM sys_notifications_receiver r
        WHERE r.notification_id = n.id AND r.user_id = #{userId}
    )
)

NOT EXISTS (
    SELECT 1 FROM sys_notifications_receiver r
    WHERE r.notification_id = n.id AND r.user_id = #{userId}
      AND (r.send_code = n.send_code OR r.send_code IS NULL)
      AND r.is_read = 1 AND r.is_deleted = 0
)

NOT EXISTS (
    SELECT 1 FROM sys_notifications_receiver r
    WHERE r.notification_id = n.id AND r.user_id = #{userId}
      AND (r.send_code = n.send_code OR r.send_code IS NULL)
      AND r.is_deleted = 1
)

mapper.select:
select n.id, n.from_user_id, n.business_id, n.business_type, n.category, n.title, n.message, n.link, n.create_time, u.nickname as to_nickname, u1.nickname as from_nickname, COALESCE(e.title, '') as business_title,
c.comment_type as comment_type, c.business_id as comment_business_id, CASE WHEN EXISTS ( SELECT 1 FROM sys_notifications_receiver r WHERE r.notification_id = n.id AND r.user_id = #{userId} AND (r.send_code = n.send_code OR r.send_code IS NULL) AND r.is_read = 1 AND r.is_deleted = 0 ) THEN 1 ELSE 0 END AS is_read from sys_notifications n left join sys_user u on u.id = left join sys_user u1 on n.from_user_id = u1.id left join sys_notice e on n.business_id = e.id and n.business_type = 'notice' left join sys_comment c on n.business_id = c.id and n.business_type in ('comment', 'like')
n.del_flag = 0 and and
and n.category = #{notifications.category}
and n.business_type = #{notifications.businessType}
and n.business_type IN
#{item}
order by is_read asc, n.create_time desc

select n.id, n.from_user_id, n.business_id, n.business_type, n.category, n.title, n.message, n.link, n.notice_push,
(select count(1) from sys_notifications_receiver r where r.notification_id = n.id and (r.send_code = n.send_code or r.send_code is null) and r.is_read = 1 and r.is_deleted = 0) as read_count, n.del_flag, n.create_time, u1.nickname as from_nickname, COALESCE(e.title, '') as business_title from sys_notifications n left join sys_user u1 on n.from_user_id = u1.id left join sys_notice e on n.business_id = e.id and n.business_type = 'notice'
and n.business_type = #{notifications.businessType}
and n.business_type IN
#{item}
and n.del_flag = #{notifications.delFlag}
and n.title like concat('%', #{notifications.title}, '%')
and u1.nickname like concat('%', #{notifications.fromNickname}, '%')
order by n.del_flag asc, n.create_time desc

mapper.insert:
insert into sys_notifications_receiver (notification_id, user_id, send_code, is_read, read_time, is_deleted, create_time) select n.id, #{userId}, n.send_code, 1, now(), 0, now() from sys_notifications n where n.del_flag = 0 and and and
and n.category = #{category}
on duplicate key update send_code = values(send_code), is_read = 1, read_time = now(), is_deleted = 0

insert ignore into sys_notifications_receiver (notification_id, send_code, user_id, is_read, read_time, is_deleted, create_time)
select #{notificationId}, #{sendCode}, u.id, 0, null, 0, now()
from sys_user u
where u.status = 1
  and (
    1 = 0

        or u.id in
        #{id}


        or exists (
            select 1 from sys_dept_user du
            where du.user_id = u.id and du.dept_id in
            #{id}
        )


        or exists (
            select 1 from sys_user_role ur
            where ur.user_id = u.id and ur.role_id in
            #{id}
        )

  )
